(() => {
 const project=window.portfolioProjects.find(p=>p.id===new URLSearchParams(location.search).get('id'));
 const host=document.querySelector('#case-main');
 const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 if(!project){document.title='Project not found — Ridham Sonani';host.innerHTML='<section class="wrap section"><p class="eyebrow">PROJECT NOT FOUND</p><h1>Let’s get you back<br>to the work.</h1><a class="button primary" href="index.html#work">Explore all projects ↗</a></section>';return;}
 const p=project;
 document.title=`${p.name} — Ridham Sonani`;
 document.querySelector('meta[name="description"]').content=p.subtitle;
 const tags=values=>`<div class="tags">${values.map(t=>`<span>${esc(t)}</span>`).join('')}</div>`;
 const link=(url,label)=>`<a class="text-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label} <span aria-hidden="true">↗</span></a>`;
 const resources=`${p.github?link(p.github,'View on GitHub'):''}${p.asu?link(p.asu,'Read the ASU story'):''}`;
 const nav=[['overview','The problem'],['contribution','My contribution'],['architecture','System architecture'],['decisions','Key decisions'],['challenges','Challenges & solutions'],['validation','Testing & delivery'],['outcome','Results & reflection'],['resources','Project resources']];
 const index=window.portfolioProjects.indexOf(p);
 const next=window.portfolioProjects[(index+1)%window.portfolioProjects.length];
 const resultIntro=p.group==='cic'?'Collaborative prototype':'Academic implementation';
 host.innerHTML=`<div class="case-hero wrap"><a class="back-link" href="index.html#work">← All projects</a><div class="case-heading"><div><p class="eyebrow section-number">${p.group==='cic'?'ASU AI CLOUD INNOVATION CENTER':'COURSEWORK'} / CASE STUDY ${String(index+1).padStart(2,'0')}</p><h1>${esc(p.name)}</h1><p class="case-subtitle">${esc(p.subtitle)}</p></div><span class="case-index" aria-hidden="true">${String(index+1).padStart(2,'0')}</span></div><div class="case-meta"><div><span>MY ROLE</span><strong>${esc(p.roleLabel)}</strong></div><div><span>${p.group==='cic'?'COLLABORATION':'CONTEXT'}</span><strong>${esc(p.client)}</strong></div><div><span>PERIOD / CONTEXT</span><strong>${esc(p.period)}</strong></div></div><div class="case-links">${resources}${tags(p.tags)}</div></div>
 <div class="wrap case-cover"><div class="case-cover-art">${window.portfolioArtwork(p.art)}</div><div class="case-cover-info"><span class="eyebrow">AT A GLANCE</span>${p.signals.map(([value,label])=>`<div><strong>${esc(value)}</strong><span>${esc(label)}</span></div>`).join('')}<small>${p.id==='blood-centers'?'UAT result reported in the supplied project documentation.':'Conceptual illustration of the project’s domain.'}</small></div></div>
 <div class="wrap case-layout"><aside class="case-sidebar" aria-label="Case study contents"><p class="eyebrow">IN THIS CASE STUDY</p><nav aria-label="Case study sections">${nav.map(([id,label],i)=>`<a href="#${id}"><span>${String(i+1).padStart(2,'0')}</span>${label}</a>`).join('')}</nav><a class="sidebar-contact" href="mailto:rsonani@asu.edu?subject=${encodeURIComponent('Let’s talk about '+p.name)}">Ask me about this project ↗</a></aside><div class="case-content">
 <section class="case-section" id="overview"><p class="eyebrow">01 / CONTEXT</p><h2>The problem worth solving.</h2><p class="case-lede">${esc(p.problem)}</p><p>${esc(p.summary)}</p><div class="project-context"><strong>${esc(resultIntro)}</strong><p>${p.group==='cic'?'Developed through ASU’s AI Cloud Innovation Center with partner stakeholders and AWS/ASU mentors. The case study describes the project implementation and my specific contributions.':'A coursework project focused on implementation and engineering fundamentals. Supplied tooling and project boundaries are called out below.'}</p></div></section>
 <section class="case-section" id="contribution"><p class="eyebrow">02 / OWNERSHIP</p><h2>Where I contributed.</h2><p>${esc(p.role)}</p><ul class="contribution-list">${p.contributions.map((item,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><p>${esc(item)}</p></li>`).join('')}</ul></section>
 <section class="case-section" id="architecture"><p class="eyebrow">03 / SYSTEM DESIGN</p><h2>How the pieces fit together.</h2><p>Following the data from input to a useful result.</p>${p.architecture.map((flow,i)=>`<div class="flow-panel"><h3><span>${String(i+1).padStart(2,'0')}</span>${esc(flow.name)}</h3><ol class="flow-steps">${flow.steps.map(([title,text],j)=>`<li><span class="flow-number">${j+1}</span><div><h4>${esc(title)}</h4><p>${esc(text)}</p></div></li>`).join('')}</ol></div>`).join('')}
 ${p.diagram?`<figure class="source-diagram"><a href="${esc(p.diagram)}" target="_blank" rel="noopener noreferrer"><img src="${esc(p.diagram)}" alt="Original architecture diagram for ${esc(p.name)}" loading="lazy"></a><figcaption>Original project architecture · <a href="${esc(p.diagram)}" target="_blank" rel="noopener noreferrer">Open full-size diagram ↗</a></figcaption></figure>`:''}
 <h3 class="table-heading">Component responsibilities</h3><div class="table-scroll" tabindex="0" role="region" aria-label="System components"><table><thead><tr><th>Layer</th><th>Technology</th><th>Responsibility</th></tr></thead><tbody>${p.components.map(row=>`<tr>${row.map(value=>`<td>${esc(value)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>
 <section class="case-section" id="decisions"><p class="eyebrow">04 / TRADE-OFFS</p><h2>Why this approach.</h2><div class="decision-list">${p.decisions.map(([title,text],i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><div><h3>${esc(title)}</h3><p>${esc(text)}</p></div></article>`).join('')}</div></section>
 <section class="case-section" id="challenges"><p class="eyebrow">05 / ENGINEERING DETAILS</p><h2>The hard parts, made workable.</h2>${p.challenges.map(([title,problem,solution])=>`<article class="challenge-block"><h3>${esc(title)}</h3><p><strong>The constraint</strong>${esc(problem)}</p><p><strong>The approach</strong>${esc(solution)}</p></article>`).join('')}</section>
 <section class="case-section" id="validation"><p class="eyebrow">06 / CONFIDENCE & HANDOFF</p><h2>Testing the whole path.</h2><ul class="validation-list">${p.validation.map(item=>`<li>${esc(item)}</li>`).join('')}</ul><h3>Deployment, security & operations</h3><p>${esc(p.deployment)}</p></section>
 ${p.gallery?`<section class="case-section case-gallery" id="interface"><p class="eyebrow">THE INTERFACE</p><h2>From system to experience.</h2>${p.gallery.map(([src,caption])=>`<figure><a href="${esc(src)}" target="_blank" rel="noopener noreferrer"><img src="${esc(src)}" alt="${esc(caption)}" loading="lazy" width="1600" height="1040"></a><figcaption>${esc(caption)} <a href="${esc(p.asu)}" target="_blank" rel="noopener noreferrer">Source: ASU CIC ↗</a></figcaption></figure>`).join('')}</section>`:''}
 <section class="case-section" id="outcome"><p class="eyebrow">07 / WHAT CAME OUT OF IT</p><h2>The result. And the learning.</h2><p class="case-lede">${esc(p.outcome)}</p><blockquote>${esc(p.learning)}</blockquote><h3>Future directions</h3><p class="future-note">Potential next steps, separate from the delivered implementation.</p><ul>${p.next.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></section>
 <section class="case-section" id="resources"><p class="eyebrow">08 / GO DEEPER</p><h2>Explore the project.</h2>${tags(p.stack)}<div class="case-resource-cards">${p.github?`<a href="${esc(p.github)}" target="_blank" rel="noopener noreferrer"><span>SOURCE CODE</span><strong>GitHub repository ↗</strong><small>${esc(new URL(p.github).pathname.replace(/^\//,''))}</small></a>`:'<div><span>SOURCE CODE</span><strong>Coursework repository</strong><small>Not published yet.</small></div>'}${p.asu?`<a href="${esc(p.asu)}" target="_blank" rel="noopener noreferrer"><span>OFFICIAL PROJECT STORY</span><strong>ASU Cloud Innovation Center ↗</strong><small>Partner context, approach, and student spotlight</small></a>`:''}</div><p class="resource-note">Case-study detail is based on my technical project documentation.${p.asu?' The ASU story and linked repository provide additional public context.':''} Conceptual artwork is illustrative; screenshots and original diagrams are labelled.</p></section>
 </div></div><section class="case-next wrap"><span class="eyebrow">NEXT CASE STUDY</span><a href="project.html?id=${next.id}"><h2>${esc(next.name)}</h2><span aria-hidden="true">↗</span></a><a class="text-link" href="index.html#work">← Back to all work</a></section>`;
 if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting)document.querySelectorAll('.case-sidebar nav a').forEach(a=>{if(a.hash===`#${entry.target.id}`)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});}),{rootMargin:'-15% 0px -65% 0px'});document.querySelectorAll('.case-section[id]').forEach(section=>observer.observe(section));}
})();
